using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SIFTC.Domain.Entities;

namespace SIFTC.Infrastructure.Persistence.Configurations;

public sealed class RolSistemaConfiguration : IEntityTypeConfiguration<RolSistema>
{
    public void Configure(EntityTypeBuilder<RolSistema> b)
    {
        b.ToTable("roles", "seguridad"); b.HasKey(x => x.IdRol); b.Property(x => x.IdRol).HasColumnName("id_rol").HasDefaultValueSql("gen_random_uuid()");
        b.Property(x => x.Nombre).HasColumnName("nombre").HasMaxLength(30).IsRequired(); b.HasIndex(x => x.Nombre).IsUnique();
        b.Property(x => x.Descripcion).HasColumnName("descripcion").HasMaxLength(150); b.Property(x => x.PermisosClave).HasColumnName("permisos_clave").HasMaxLength(60).IsRequired();
    }
}

public sealed class LoteCargaConfiguration : IEntityTypeConfiguration<LoteCarga>
{
    public void Configure(EntityTypeBuilder<LoteCarga> b)
    {
        b.ToTable("lotes_carga", "cruda"); b.HasKey(x => x.IdLote); b.Property(x => x.IdLote).HasColumnName("id_lote").HasDefaultValueSql("gen_random_uuid()");
        b.Property(x => x.NombreArchivo).HasColumnName("nombre_archivo").HasMaxLength(150).IsRequired(); b.Property(x => x.FechaCarga).HasColumnName("fecha_carga").HasDefaultValueSql("now()");
        b.Property(x => x.RegistrosTotales).HasColumnName("registros_totales").HasDefaultValue(0); b.Property(x => x.RegistrosValidos).HasColumnName("registros_validos").HasDefaultValue(0);
        b.Property(x => x.IndiceCalidad).HasColumnName("indice_calidad").HasPrecision(5, 2).ValueGeneratedOnAddOrUpdate(); b.Property(x => x.IdUsuario).HasColumnName("id_usuario"); b.HasIndex(x => x.IdUsuario).HasDatabaseName("ix_lotes_usuario");
        b.HasOne(x => x.Usuario).WithMany().HasForeignKey(x => x.IdUsuario).OnDelete(DeleteBehavior.Restrict);
    }
}

public sealed class MatrizFinancieraCrudaConfiguration : IEntityTypeConfiguration<MatrizFinancieraCruda>
{
    public void Configure(EntityTypeBuilder<MatrizFinancieraCruda> b)
    {
        b.ToTable("ext_matriz_financiera_entidades", "cruda"); b.HasKey(x => x.IdCruda); b.Property(x => x.IdCruda).HasColumnName("id_cruda").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.IdLote).HasColumnName("id_lote"); b.HasIndex(x => x.IdLote).HasDatabaseName("ix_ext_matriz_lote");
        b.HasOne(x => x.Lote).WithMany(x => x.RegistrosCrudos).HasForeignKey(x => x.IdLote).OnDelete(DeleteBehavior.Restrict);
        b.Property(x => x.CodigoEntidad).HasColumnName("codigo_entidad"); b.Property(x => x.NombreEntidad).HasColumnName("nombre_entidad"); b.Property(x => x.Sector).HasColumnName("sector"); b.Property(x => x.Periodo).HasColumnName("periodo"); b.Property(x => x.UtilidadNeta).HasColumnName("utilidad_neta"); b.Property(x => x.Patrimonio).HasColumnName("patrimonio"); b.Property(x => x.ActivosTotales).HasColumnName("activos_totales"); b.Property(x => x.Ebitda).HasColumnName("ebitda"); b.Property(x => x.Ingresos).HasColumnName("ingresos"); b.Property(x => x.ActivoCorriente).HasColumnName("activo_corriente"); b.Property(x => x.PasivoCorriente).HasColumnName("pasivo_corriente"); b.Property(x => x.Inventarios).HasColumnName("inventarios"); b.Property(x => x.PasivoTotal).HasColumnName("pasivo_total"); b.Property(x => x.Ebit).HasColumnName("ebit"); b.Property(x => x.GastosFinancieros).HasColumnName("gastos_financieros"); b.Property(x => x.FechaCarga).HasColumnName("fecha_carga").HasDefaultValueSql("now()");
    }
}

public sealed class SectorConfiguration : IEntityTypeConfiguration<Sector> { public void Configure(EntityTypeBuilder<Sector> b) { b.ToTable("tbl_sectores", "limpia"); b.HasKey(x => x.IdSector); b.Property(x => x.IdSector).HasColumnName("id_sector").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.Nombre).HasColumnName("nombre").HasMaxLength(30).IsRequired(); b.HasIndex(x => x.Nombre).IsUnique(); } }
public sealed class EntidadConfiguration : IEntityTypeConfiguration<Entidad> { public void Configure(EntityTypeBuilder<Entidad> b) { b.ToTable("tbl_entidades", "limpia"); b.HasKey(x => x.IdEntidad); b.Property(x => x.IdEntidad).HasColumnName("id_entidad").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.Ticker).HasColumnName("ticker").HasMaxLength(10).IsRequired(); b.HasIndex(x => x.Ticker).IsUnique(); b.Property(x => x.Nombre).HasColumnName("nombre").HasMaxLength(80).IsRequired(); b.Property(x => x.IdSector).HasColumnName("id_sector"); b.HasIndex(x => x.IdSector).HasDatabaseName("ix_entidades_sector"); b.HasOne(x => x.Sector).WithMany(x => x.Entidades).HasForeignKey(x => x.IdSector).OnDelete(DeleteBehavior.Restrict); } }
public sealed class DatoFinancieroConfiguration : IEntityTypeConfiguration<DatoFinanciero> { public void Configure(EntityTypeBuilder<DatoFinanciero> b) { b.ToTable("tbl_datos_financieros", "limpia"); b.HasKey(x => x.IdDato); b.Property(x => x.IdDato).HasColumnName("id_dato").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.Periodo).HasColumnName("periodo"); foreach (var p in new[] { nameof(DatoFinanciero.UtilidadNeta), nameof(DatoFinanciero.Patrimonio), nameof(DatoFinanciero.ActivosTotales), nameof(DatoFinanciero.PasivoTotal), nameof(DatoFinanciero.ActivoCorriente), nameof(DatoFinanciero.PasivoCorriente), nameof(DatoFinanciero.Inventarios), nameof(DatoFinanciero.Ebitda), nameof(DatoFinanciero.Ebit), nameof(DatoFinanciero.Ingresos), nameof(DatoFinanciero.GastosFinancieros) }) b.Property(p).HasPrecision(15, 2); b.Property(x => x.UtilidadNeta).HasColumnName("utilidad_neta"); b.Property(x => x.Patrimonio).HasColumnName("patrimonio"); b.Property(x => x.ActivosTotales).HasColumnName("activos_totales"); b.Property(x => x.PasivoTotal).HasColumnName("pasivo_total"); b.Property(x => x.ActivoCorriente).HasColumnName("activo_corriente"); b.Property(x => x.PasivoCorriente).HasColumnName("pasivo_corriente"); b.Property(x => x.Inventarios).HasColumnName("inventarios"); b.Property(x => x.Ebitda).HasColumnName("ebitda"); b.Property(x => x.Ebit).HasColumnName("ebit"); b.Property(x => x.Ingresos).HasColumnName("ingresos"); b.Property(x => x.GastosFinancieros).HasColumnName("gastos_financieros"); b.Property(x => x.FechaCarga).HasColumnName("fecha_carga").HasDefaultValueSql("now()"); b.Property(x => x.IdLote).HasColumnName("id_lote"); b.Property(x => x.IdEntidad).HasColumnName("id_entidad"); b.Property(x => x.IdRegistroOrigen).HasColumnName("id_registro_origen"); b.HasIndex(x => x.IdRegistroOrigen).IsUnique(); b.HasIndex(x => new { x.IdEntidad, x.Periodo }).IsUnique(); b.HasIndex(x => x.IdLote).HasDatabaseName("ix_datos_fin_lote"); b.HasIndex(x => x.Periodo).HasDatabaseName("ix_datos_fin_periodo"); b.HasOne(x => x.Entidad).WithMany(x => x.DatosFinancieros).HasForeignKey(x => x.IdEntidad).OnDelete(DeleteBehavior.Restrict); } }

