public sealed class MetricaConfiguration : IEntityTypeConfiguration<Metrica> { public void Configure(EntityTypeBuilder<Metrica> b) { b.ToTable("dim_metrica", "analitica"); b.HasKey(x => x.IdMetrica); b.Property(x => x.IdMetrica).HasColumnName("id_metrica").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.Codigo).HasColumnName("codigo").HasMaxLength(10).IsRequired(); b.HasIndex(x => x.Codigo).IsUnique(); b.Property(x => x.Nombre).HasColumnName("nombre").HasMaxLength(50).IsRequired(); b.Property(x => x.Formula).HasColumnName("formula").HasMaxLength(120).IsRequired(); b.Property(x => x.Frecuencia).HasColumnName("frecuencia").HasMaxLength(12).IsRequired(); b.Property(x => x.IdDimension).HasColumnName("id_dimension"); b.HasIndex(x => x.IdDimension).HasDatabaseName("ix_metricas_dimension"); b.HasOne(x => x.Dimension).WithMany(x => x.Metricas).HasForeignKey(x => x.IdDimension).OnDelete(DeleteBehavior.Restrict); } }
public sealed class ValorMetricaConfiguration : IEntityTypeConfiguration<ValorMetrica> { public void Configure(EntityTypeBuilder<ValorMetrica> b) { b.ToTable("fct_valores_metrica", "analitica"); b.HasKey(x => x.IdValor); b.Property(x => x.IdValor).HasColumnName("id_valor").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.Periodo).HasColumnName("periodo"); b.Property(x => x.Valor).HasColumnName("valor").HasPrecision(14, 6); b.Property(x => x.ValorNormalizado).HasColumnName("valor_normalizado").HasPrecision(9, 8); b.Property(x => x.FechaCarga).HasColumnName("fecha_carga").HasDefaultValueSql("now()"); b.Property(x => x.IdLote).HasColumnName("id_lote"); b.Property(x => x.IdEntidad).HasColumnName("id_entidad"); b.Property(x => x.IdMetrica).HasColumnName("id_metrica"); b.Property(x => x.IdRegistroOrigen).HasColumnName("id_registro_origen"); b.HasIndex(x => new { x.IdEntidad, x.IdMetrica, x.Periodo }).IsUnique(); b.HasIndex(x => x.IdLote).HasDatabaseName("ix_valores_lote"); b.HasIndex(x => x.IdMetrica).HasDatabaseName("ix_valores_metrica"); b.HasIndex(x => x.IdRegistroOrigen).HasDatabaseName("ix_valores_origen"); } }
public sealed class IndiceCompetitividadConfiguration : IEntityTypeConfiguration<IndiceCompetitividad> { public void Configure(EntityTypeBuilder<IndiceCompetitividad> b) { b.ToTable("fct_indices_competitividad", "analitica"); b.HasKey(x => x.IdIndice); b.Property(x => x.IdIndice).HasColumnName("id_indice").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.FechaCarga).HasColumnName("fecha_carga").HasDefaultValueSql("now()"); b.Property(x => x.Ic).HasColumnName("ic").HasPrecision(6, 3); b.Property(x => x.IdLote).HasColumnName("id_lote"); b.Property(x => x.IdEntidad).HasColumnName("id_entidad"); b.HasIndex(x => new { x.IdEntidad, x.IdLote }).IsUnique(); b.HasIndex(x => x.IdLote).HasDatabaseName("ix_indices_lote"); b.HasIndex(x => x.FechaCarga).HasDatabaseName("ix_indices_fecha"); } }
public sealed class CotizacionConfiguration : IEntityTypeConfiguration<Cotizacion> { public void Configure(EntityTypeBuilder<Cotizacion> b) { b.ToTable("fct_cotizaciones", "analitica"); b.HasKey(x => x.IdCotizacion); b.Property(x => x.IdCotizacion).HasColumnName("id_cotizacion").HasDefaultValueSql("gen_random_uuid()"); b.Property(x => x.Fecha).HasColumnName("fecha"); b.Property(x => x.Apertura).HasColumnName("apertura").HasPrecision(6, 3); b.Property(x => x.Maximo).HasColumnName("maximo").HasPrecision(6, 3); b.Property(x => x.Minimo).HasColumnName("minimo").HasPrecision(6, 3); b.Property(x => x.Cierre).HasColumnName("cierre").HasPrecision(6, 3); b.Property(x => x.VariacionPct).HasColumnName("variacion_pct").HasPrecision(8, 4); b.Property(x => x.VolumenActualizaciones).HasColumnName("volumen_actualizaciones").HasDefaultValue(0); b.Property(x => x.FechaCarga).HasColumnName("fecha_carga").HasDefaultValueSql("now()"); b.Property(x => x.IdEntidad).HasColumnName("id_entidad"); b.HasIndex(x => new { x.IdEntidad, x.Fecha }).IsUnique(); b.HasOne(x => x.Entidad).WithMany(x => x.Cotizaciones).HasForeignKey(x => x.IdEntidad).OnDelete(DeleteBehavior.Restrict); } }
